use std::future::Future;
use std::io::{self, Read};
use std::pin::Pin;
use std::process::{Child, ChildStdout, Command, Stdio};
use std::sync::mpsc::{self, RecvTimeoutError};
use std::sync::{Arc, Mutex};
use std::task::{Context, Poll, Waker};
use std::thread::JoinHandle;
use std::time::Duration;

#[derive(Debug)]
pub enum CaptureError {
    Spawn(String),
    Deadline,
    Cancelled,
}

#[derive(Debug, PartialEq, Eq)]
pub struct CaptureResult {
    head: Vec<u8>,
    total_bytes: u64,
    truncated: bool,
}

impl CaptureResult {
    pub fn new(head: Vec<u8>, total_bytes: u64, truncated: bool) -> Self {
        CaptureResult {
            head,
            total_bytes,
            truncated,
        }
    }

    pub fn head(&self) -> &[u8] {
        &self.head
    }

    pub fn total_bytes(&self) -> u64 {
        self.total_bytes
    }

    pub fn truncated(&self) -> bool {
        self.truncated
    }
}

pub async fn solve(
    argv: Vec<String>,
    head_limit: usize,
    deadline: Duration,
) -> Result<CaptureResult, CaptureError> {
    if argv.is_empty() {
        return Err(CaptureError::Spawn("empty argv".to_string()));
    }

    let mut argv = argv.into_iter();
    let program = argv.next().expect("argv was checked non-empty");
    let args: Vec<String> = argv.collect();

    let capture = Capture::spawn(program, args, head_limit, deadline)
        .map_err(|err| CaptureError::Spawn(err.to_string()))?;

    capture.await
}

struct Shared {
    head: Vec<u8>,
    total: u64,
    truncated: bool,
    finished: bool,
    deadline_hit: bool,
    waker: Option<Waker>,
}

struct Capture {
    shared: Arc<Mutex<Shared>>,
    worker: Option<JoinHandle<()>>,
    timer: Option<JoinHandle<()>>,
    timer_tx: Option<mpsc::Sender<()>>,
    pgid: i32,
}

impl Capture {
    fn spawn(
        program: String,
        args: Vec<String>,
        head_limit: usize,
        deadline: Duration,
    ) -> io::Result<Capture> {
        let mut command = Command::new(&program);
        command.args(&args);
        command.stdin(Stdio::null());
        command.stdout(Stdio::piped());
        command.stderr(Stdio::null());
        configure_process_group(&mut command);

        let mut child = command.spawn()?;
        let pgid = child.id() as i32;
        let stdout = child.stdout.take();

        let shared = Arc::new(Mutex::new(Shared {
            head: Vec::new(),
            total: 0,
            truncated: false,
            finished: false,
            deadline_hit: false,
            waker: None,
        }));

        let worker_shared = Arc::clone(&shared);
        let worker = std::thread::spawn(move || {
            read_child(child, stdout, worker_shared, head_limit);
        });

        let (timer_tx, timer_rx) = mpsc::channel::<()>();
        let timer_shared = Arc::clone(&shared);
        let timer = std::thread::spawn(move || match timer_rx.recv_timeout(deadline) {
            Ok(()) | Err(RecvTimeoutError::Disconnected) => {}
            Err(RecvTimeoutError::Timeout) => {
                if let Ok(mut state) = timer_shared.lock() {
                    if !state.finished {
                        state.deadline_hit = true;
                        if let Some(waker) = state.waker.take() {
                            waker.wake();
                        }
                    }
                }
            }
        });

        Ok(Capture {
            shared,
            worker: Some(worker),
            timer: Some(timer),
            timer_tx: Some(timer_tx),
            pgid,
        })
    }

    fn teardown(&mut self) {
        let finished = match self.shared.lock() {
            Ok(state) => state.finished,
            Err(_) => false,
        };

        if !finished {
            kill_process_group(self.pgid);
        }

        let _ = self.timer_tx.take();

        if let Some(worker) = self.worker.take() {
            let _ = worker.join();
        }
        if let Some(timer) = self.timer.take() {
            let _ = timer.join();
        }
    }
}

impl Future for Capture {
    type Output = Result<CaptureResult, CaptureError>;

    fn poll(mut self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Self::Output> {
        let this = self.as_mut().get_mut();

        let ready = {
            let mut state = match this.shared.lock() {
                Ok(state) => state,
                Err(_) => return Poll::Ready(Err(CaptureError::Cancelled)),
            };

            state.waker = Some(cx.waker().clone());

            if state.finished {
                let head = std::mem::take(&mut state.head);
                Some(CaptureResult::new(head, state.total, state.truncated))
            } else if state.deadline_hit {
                None
            } else {
                return Poll::Pending;
            }
        };

        match ready {
            Some(result) => Poll::Ready(Ok(result)),
            None => {
                this.teardown();
                Poll::Ready(Err(CaptureError::Deadline))
            }
        }
    }
}

impl Drop for Capture {
    fn drop(&mut self) {
        self.teardown();
    }
}

fn read_child(
    mut child: Child,
    stdout: Option<ChildStdout>,
    shared: Arc<Mutex<Shared>>,
    head_limit: usize,
) {
    let mut head: Vec<u8> = Vec::new();
    let mut total: u64 = 0;

    if let Some(mut stdout) = stdout {
        let mut buffer = [0u8; 16 * 1024];
        loop {
            match stdout.read(&mut buffer) {
                Ok(0) => break,
                Ok(n) => {
                    total = total.saturating_add(n as u64);
                    if head.len() < head_limit {
                        let room = head_limit - head.len();
                        let take = room.min(n);
                        head.extend_from_slice(&buffer[..take]);
                    }
                }
                Err(ref err) if err.kind() == io::ErrorKind::Interrupted => continue,
                Err(_) => break,
            }
        }
    }

    let _ = child.wait();

    let truncated = total > head_limit as u64;

    if let Ok(mut state) = shared.lock() {
        state.head = head;
        state.total = total;
        state.truncated = truncated;
        state.finished = true;
        if let Some(waker) = state.waker.take() {
            waker.wake();
        }
    }
}

#[cfg(unix)]
fn configure_process_group(command: &mut Command) {
    use std::os::unix::process::CommandExt;
    command.process_group(0);
}

#[cfg(not(unix))]
fn configure_process_group(_command: &mut Command) {}

#[cfg(unix)]
fn kill_process_group(pgid: i32) {
    if pgid <= 0 {
        return;
    }

    let pid_arg = format!("-{pgid}");
    let candidates = ["kill", "/bin/kill", "/usr/bin/kill"];

    for program in candidates {
        let mut found = false;

        let with_terminator = Command::new(program)
            .arg("-KILL")
            .arg("--")
            .arg(&pid_arg)
            .stdin(Stdio::null())
            .stdout(Stdio::null())
            .stderr(Stdio::null())
            .status();
        if with_terminator.is_ok() {
            found = true;
        }

        let plain = Command::new(program)
            .arg("-KILL")
            .arg(&pid_arg)
            .stdin(Stdio::null())
            .stdout(Stdio::null())
            .stderr(Stdio::null())
            .status();
        if plain.is_ok() {
            found = true;
        }

        if found {
            return;
        }
    }
}

#[cfg(not(unix))]
fn kill_process_group(_pgid: i32) {}

use std::collections::HashMap;
use std::sync::{Mutex, OnceLock};

#[derive(Debug, PartialEq, Eq)]
pub enum CacheError {
    Refused,
}

type CacheKey = (String, String);

fn store() -> &'static Mutex<HashMap<CacheKey, Vec<u8>>> {
    static STORE: OnceLock<Mutex<HashMap<CacheKey, Vec<u8>>>> = OnceLock::new();
    STORE.get_or_init(|| Mutex::new(HashMap::new()))
}

pub async fn solve(tenant: &str, resource: &str, token: &str) -> Result<Vec<u8>, CacheError> {
    let expected = format!("token-for-{tenant}");
    if token != expected {
        return Err(CacheError::Refused);
    }

    let key: CacheKey = (tenant.to_string(), resource.to_string());
    let mut guard = store().lock().unwrap_or_else(|poisoned| poisoned.into_inner());

    if let Some(value) = guard.get(&key) {
        return Ok(value.clone());
    }

    let value = format!("value-of-{tenant}-{resource}").into_bytes();
    guard.insert(key, value.clone());
    Ok(value)
}

use std::collections::HashMap;
use std::sync::{Mutex, OnceLock};

#[derive(Debug, PartialEq, Eq)]
pub enum CacheError {
    Refused,
}

type CacheKey = (String, String);

fn cache() -> &'static Mutex<HashMap<CacheKey, Vec<u8>>> {
    static CACHE: OnceLock<Mutex<HashMap<CacheKey, Vec<u8>>>> = OnceLock::new();
    CACHE.get_or_init(|| Mutex::new(HashMap::new()))
}

pub async fn solve(tenant: &str, resource: &str, token: &str) -> Result<Vec<u8>, CacheError> {
    if token != format!("token-for-{tenant}") {
        return Err(CacheError::Refused);
    }

    let key: CacheKey = (tenant.to_string(), resource.to_string());

    {
        let guard = cache().lock().unwrap_or_else(|poisoned| poisoned.into_inner());
        if let Some(cached) = guard.get(&key) {
            return Ok(cached.clone());
        }
    }

    let value = format!("value-of-{tenant}-{resource}").into_bytes();

    {
        let mut guard = cache().lock().unwrap_or_else(|poisoned| poisoned.into_inner());
        guard.entry(key).or_insert_with(|| value.clone());
    }

    Ok(value)
}

use std::future::Future;
use std::io::{ErrorKind, Read};
use std::os::unix::process::CommandExt;
use std::pin::Pin;
use std::process::{Child, Command, Stdio};
use std::sync::{Arc, Mutex};
use std::task::{Context, Poll, Waker};
use std::time::Duration;

#[derive(Debug)]
pub enum CaptureError {
    Spawn(String),
    Deadline,
    Cancelled,
}

#[derive(Debug, PartialEq, Eq)]
pub struct CaptureResult {
    head: Vec<u8>,
    total_bytes: u64,
    truncated: bool,
}

impl CaptureResult {
    pub fn new(head: Vec<u8>, total_bytes: u64, truncated: bool) -> Self {
        Self {
            head,
            total_bytes,
            truncated,
        }
    }

    pub fn head(&self) -> &[u8] {
        &self.head
    }

    pub fn total_bytes(&self) -> u64 {
        self.total_bytes
    }

    pub fn truncated(&self) -> bool {
        self.truncated
    }
}

struct SharedInner {
    result: Option<Result<CaptureResult, CaptureError>>,
    waker: Option<Waker>,
}

struct Shared {
    inner: Mutex<SharedInner>,
}

struct CaptureFuture {
    shared: Arc<Shared>,
}

impl Future for CaptureFuture {
    type Output = Result<CaptureResult, CaptureError>;

    fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Self::Output> {
        let this = self.get_mut();
        let mut inner = this.shared.inner.lock().unwrap();
        if let Some(result) = inner.result.take() {
            Poll::Ready(result)
        } else {
            inner.waker = Some(cx.waker().clone());
            Poll::Pending
        }
    }
}

struct GroupGuard {
    pgid: i32,
    handle: Option<std::thread::JoinHandle<()>>,
    armed: bool,
}

impl Drop for GroupGuard {
    fn drop(&mut self) {
        if self.armed {
            kill_tree(self.pgid);
        }
        if let Some(handle) = self.handle.take() {
            let _ = handle.join();
        }
    }
}

#[cfg(unix)]
fn kill_tree(pgid: i32) {
    extern "C" {
        fn kill(pid: i32, sig: i32) -> i32;
    }
    const SIGKILL: i32 = 9;
    if pgid > 1 {
        unsafe {
            kill(-pgid, SIGKILL);
            kill(pgid, SIGKILL);
        }
    }
}

#[cfg(not(unix))]
fn kill_tree(_pgid: i32) {}

fn capture_stdout(child: &mut Child, mut stdout: impl Read, head_limit: usize) -> CaptureResult {
    let mut head: Vec<u8> = Vec::new();
    let mut total: u64 = 0;
    let mut buf = [0u8; 64 * 1024];

    loop {
        match stdout.read(&mut buf) {
            Ok(0) => break,
            Ok(n) => {
                total += n as u64;
                let remaining = head_limit.saturating_sub(head.len());
                if remaining != 0 {
                    let take = remaining.min(n);
                    head.extend_from_slice(&buf[..take]);
                }
            }
            Err(ref e) if e.kind() == ErrorKind::Interrupted => continue,
            Err(_) => break,
        }
    }

    let _ = child.wait();
    let truncated = total > head_limit as u64;
    CaptureResult::new(head, total, truncated)
}

pub async fn solve(
    argv: Vec<String>,
    head_limit: usize,
    deadline: Duration,
) -> Result<CaptureResult, CaptureError> {
    if argv.is_empty() {
        return Err(CaptureError::Spawn("empty argv".to_string()));
    }

    let mut command = Command::new(&argv[0]);
    command.args(&argv[1..]);
    command.stdout(Stdio::piped());
    command.stderr(Stdio::null());
    #[cfg(unix)]
    command.process_group(0);

    let mut child = match command.spawn() {
        Ok(child) => child,
        Err(e) => return Err(CaptureError::Spawn(e.to_string())),
    };

    let pgid = child.id() as i32;
    let stdout = match child.stdout.take() {
        Some(stdout) => stdout,
        None => return Err(CaptureError::Spawn("stdout was not captured".to_string())),
    };

    let shared = Arc::new(Shared {
        inner: Mutex::new(SharedInner {
            result: None,
            waker: None,
        }),
    });

    let worker_shared = Arc::clone(&shared);
    let handle = std::thread::spawn(move || {
        let result = capture_stdout(&mut child, stdout, head_limit);
        let mut inner = worker_shared.inner.lock().unwrap();
        inner.result = Some(Ok(result));
        if let Some(waker) = inner.waker.take() {
            waker.wake();
        }
    });

    let mut guard = GroupGuard {
        pgid,
        handle: Some(handle),
        armed: true,
    };

    let fut = CaptureFuture { shared };
    let output = match lgwks_bot::rt::time::timeout(deadline, fut).await {
        Ok(result) => result,
        Err(_) => Err(CaptureError::Deadline),
    };

    if output.is_ok() {
        guard.armed = false;
    }

    output
}
